-- wave151 (27/09/26): the news banner moves from the loading screen to the top of Home.
-- Steel: "I see the news banner, I don't want [it] to be on the loading page, instead put it on the dashboard itself" (then chose Home).
-- No schema change: the page reads the same hub_reel_current(). This updates the comments, Hub module 1 and the Admin access profile.

comment on table public.hub_reel is 'The loading screen and the news banner on Home (wave149; the banner moved to Home in wave151). kind lesson, learning, milestone: the loading screen''s lines for the week (batch = Monday, Toronto time; rebuilt once a week by hub-reel from wa_lessons, form_summaries, social_notes, search_top, wa_history and goal_wins, phrased by the model). kind news: the news banner at the top of Home (batch = the day; rebuilt every morning from servings, fundraising events, new starters and wins). kind update: an admin''s own line for the news banner, shown until the day in until. hidden: taken off by an admin (Admin, Loading screen and news). Shout-outs stay in hub_shoutouts. Read through hub_reel_current() and hub_reel_admin(); nothing about leadership changes, roles or departures is written here (hub-reel filters every line).';
comment on function public.hub_reel_current() is 'The loading screen''s lines for the week (lessons, learnings and milestones, cached by the page after sign-in) and today''s news banner for the top of Home (live updates first, read live by the page), without hidden lines. Everyone on the Hub (staff, the board, admins); the banner itself shows on Home, which is for staff.';
comment on function public.hub_reel_admin() is 'Admin, Loading screen and news (wave149, wave151): the week''s lines and today''s news with ids and hidden flags, and the admins'' updates of the last 30 days. Admins only.';
comment on function public.hub_reel_hide(bigint, boolean) is 'Takes a loading screen line or a news banner item off (p_hidden true) or puts it back. Admins only; logged in change_log.';
comment on function public.hub_news_add(text, text, date) is 'Adds an admin''s update to the news banner at the top of Home (under 140 characters; link a Hub page #... or an https address; shown until p_until, two weeks by default, 90 days at most). Admins only; logged in change_log.';

update public.trainings set description = replace(description, 'Sign in and you land on My page: your open tasks', 'Sign in and you land on My page (Home). Along the top runs the news banner: what happened recently and what is coming (the next servings, thank-yous after a serving, fundraising events, people who joined a team, wins from team meetings and updates from the admins), rebuilt every morning; hover over it or press pause to stop it. Below it: your open tasks'), updated_at = now() where id = 39 and position('Sign in and you land on My page: your open tasks' in description) > 0 and position('news banner' in description) = 0;

update public.hub_access_profiles set can = (select jsonb_agg(case when x = 'The loading screen in Admin: this week''s lessons, learnings and milestones, the news banner, taking a line off and adding an update' then to_jsonb('Loading screen and news in Admin: this week''s lessons, learnings and milestones for the loading screen, the news banner at the top of Home, taking a line off and adding an update'::text) else to_jsonb(x) end order by o) from jsonb_array_elements_text(can) with ordinality as e(x, o)), updated_by = 'wave151', updated_at = now() where key = 'admin' and can::text like '%The loading screen in Admin%';

insert into public.change_log (entity_type, entity_id, field, old_value, new_value, changed_by) values ('hub_reel', 'wave151', 'news banner', 'the bottom of the loading screen', 'the top of Home (read live); the loading screen keeps its rotating lines', 'wave151');

-- the record
