 p_until, two weeks by default, 90 days at most). Admins only; logged in change_log.'$m$,$m$update public.trainings set description = replace(description, 'Sign in and you land on My page: your open tasks', 'Sign in and you land on My page (Home). Along the top runs the news banner: what happened recently and what is coming (the next servings, thank-yous after a serving, fundraising events, people who joined a team, wins from team meetings and updates from the admins), rebuilt every morning; hover over it or press pause to stop it. Below it: your open tasks'), updated_at = now() where id = 39 and position('Sign in and you land on My page: your open tasks' in description) > 0 and position('news banner' in description) = 0$m$,$m$update public.hub_access_profiles set can = (select jsonb_agg(case when x = 'The loading screen in Admin: this week''s lessons, learnings and milestones, the news banner, taking a line off and adding an update' then to_jsonb('Loading screen and news in Admin: this week''s lessons, learnings and milestones for the loading screen, the news banner at the top of Home, taking a line off and adding an update'::text) else to_jsonb(x) end order by o) from jsonb_array_elements_text(can) with ordinality as e(x, o)), updated_by = 'wave151', updated_at = now() where key = 'admin' and can::text like '%The loading screen in Admin%'$m$,$m$insert into public.change_log (entity_type, entity_id, field, old_value, new_value, changed_by) values ('hub_reel', 'wave151', 'news banner', 'the bottom of the loading screen', 'the top of Home (read live); the loading screen keeps its rotating lines', 'wave151')$m$]) on conflict (version) do update set name = excluded.name, statements = excluded.statements;
